return items.map(item => {
  const input = item.json;

  const taskId =
    input.task_id ||
    input.id ||
    input.task?.id ||
    input.payload?.task_id ||
    null;

  const taskUrl =
    input.task_url ||
    input.url ||
    input.task?.url ||
    null;

  const subject =
    input.name ||
    input.task?.name ||
    input.subject ||
    null;

  const clickupStatusRaw =
    input.status?.status ||
    input.status ||
    input.task?.status?.status ||
    input.task?.status ||
    input.payload?.status ||
    null;

  const actorName =
    input.user?.username ||
    input.user?.name ||
    input.actor?.name ||
    input.updated_by?.username ||
    'ClickUp user';

  const actorEmail =
    input.user?.email ||
    input.actor?.email ||
    input.updated_by?.email ||
    null;

  const historyItems = Array.isArray(input.history_items)
    ? input.history_items
    : [];

  const statusHistoryItem = historyItems.find(h => {
    return h.field === 'status' || h.field_name === 'status';
  });

  const isStatusChange = Boolean(statusHistoryItem);

  const oldStatusRaw =
    statusHistoryItem?.before?.status ||
    statusHistoryItem?.before ||
    statusHistoryItem?.old_value?.status ||
    statusHistoryItem?.old_value ||
    null;

  const newStatusRaw =
    statusHistoryItem?.after?.status ||
    statusHistoryItem?.after ||
    statusHistoryItem?.new_value?.status ||
    statusHistoryItem?.new_value ||
    clickupStatusRaw;

  const normalizeStatus = (value) => {
    if (!value) return null;

    const normalized = String(value)
      .toLowerCase()
      .trim()
      .replace(/\s+/g, '_')
      .replace(/-/g, '_');

    const map = {
      'to_do': 'open',
      'todo': 'open',
      'new': 'open',
      'open': 'open',

      'in_progress': 'in_progress',
      'doing': 'in_progress',
      'active': 'in_progress',

      'waiting_customer': 'waiting_customer',
      'waiting_for_customer': 'waiting_customer',
      'waiting': 'waiting_customer',

      'resolved': 'resolved',
      'done': 'resolved',

      'closed': 'closed',
      'complete': 'closed',
      'completed': 'closed',

      'escalated': 'escalated'
    };

    return map[normalized] || normalized;
  };

  const oldStatus = normalizeStatus(oldStatusRaw);
  const newStatus = normalizeStatus(newStatusRaw);

  const allowedStatuses = [
    'open',
    'in_progress',
    'waiting_customer',
    'resolved',
    'closed',
    'escalated'
  ];

  const validationErrors = [
    !taskId ? 'missing_task_id' : null,
    !isStatusChange ? 'not_status_change_event' : null,
    !newStatus ? 'missing_new_status' : null,
    newStatus && !allowedStatuses.includes(newStatus) ? 'invalid_new_status' : null
  ].filter(Boolean);

  return {
    json: {
      clickup_task_id: taskId,
      clickup_task_url: taskUrl,
      subject,

      is_status_change: isStatusChange,

      old_status_from_clickup: oldStatus,
      new_status: newStatus,

      actor_name: actorName,
      actor_email: actorEmail,

      is_valid: validationErrors.length === 0,
      validation_errors: validationErrors,

      raw_clickup_status_payload: input
    }
  };
});

