return items.map(item => {
  const ticket = item.json;
  const update = $('Normalize ClickUp Status Event').first().json;

  const currentStatus = ticket.current_status;
  const newStatus = update.new_status;

  const transitions = {
    open: ['in_progress', 'waiting_customer', 'resolved', 'closed', 'escalated'],
    in_progress: ['waiting_customer', 'resolved', 'closed', 'escalated'],
    waiting_customer: ['in_progress', 'resolved', 'closed', 'escalated'],
    resolved: ['closed', 'in_progress'],
    closed: [],
    escalated: ['in_progress', 'resolved', 'closed']
  };

  const transitionAllowed =
    currentStatus === newStatus ||
    transitions[currentStatus]?.includes(newStatus);

  return {
    json: {
      ...ticket,

      clickup_task_id: update.clickup_task_id,
      clickup_task_url: update.clickup_task_url,

      old_status: currentStatus,
      new_status: newStatus,

      actor_name: update.actor_name,
      actor_email: update.actor_email,

      transition_allowed: transitionAllowed,
      transition_error: transitionAllowed
        ? null
        : `Transition from ${currentStatus} to ${newStatus} is not allowed.`
    }
  };
});

